/* eslint-disable */

/**
 * All mutable state is behind RefCell to allow `&self` methods on the
 * wasm-bindgen wrapper. This prevents re-entrant borrow panics when:
 * - Plugin instrumentation triggers span creation inside another span's
 *   creation (e.g., http client span created during express handler)
 * - Async `flushChunk` holds a borrow across await points while other
 *   span operations need access
 */
export class WasmSpanState {
    free(): void;
    [Symbol.dispose](): void;
    addSpanEvent(span_id: bigint, name: string, time_unix_nano: bigint, attrs_buf: Uint8Array): void;
    change_queue_len(): number;
    change_queue_ptr(): number;
    /**
     * Enable telemetry on the lazily-built trace exporter.
     *
     * Must be called before the first `sendPreparedChunk`. Later calls have
     * no effect.
     *
     * # Arguments
     *
     * - `heartbeat_ms`: sets the metric-flush cadence. Set to 0 to defer to
     *   libdatadog's default interval.
     * - `runtime_id`: tags telemetry payloads with the tracer's runtime id when provided
     * - `debug_enabled`: toggles libdd-telemetry's verbose logging
     */
    enableTelemetry(heartbeat_ms: number, runtime_id: string | null | undefined, debug_enabled: boolean): void;
    /**
     * Flush the queued change-buffer operations. On success always returns
     * `true` (the bool exists only for signature symmetry with the other
     * flush methods); failures surface as a thrown error.
     */
    flushChangeQueue(): boolean;
    getDuration(span_id: bigint): bigint;
    getError(span_id: bigint): number;
    getMetaAttr(span_id: bigint, name: string): any;
    getMetaStruct(span_id: bigint, key: string): any;
    getMetricAttr(span_id: bigint, name: string): any;
    getName(span_id: bigint): string;
    getResourceName(span_id: bigint): string;
    getServiceName(span_id: bigint): string;
    getSpanEventsJson(span_id: bigint): string;
    getStart(span_id: bigint): bigint;
    getTraceMetaAttr(segment_id: bigint, name: string): any;
    getTraceMetricAttr(segment_id: bigint, name: string): any;
    getTraceOrigin(segment_id: bigint): any;
    getType(span_id: bigint): string;
    constructor(url: string, tracer_version: string, lang: string, lang_version: string, lang_interpreter: string, change_queue_size: number, string_table_input_size: number, pid: number, tracer_service: string, stats_enabled: boolean, hostname: string, env: string, app_version: string, runtime_id: string, client_computed_stats: boolean);
    /**
     * Prepare a chunk of spans for sending. Flushes the change buffer and
     * extracts spans. Returns `true` if a chunk was prepared
     * (there are spans to send) and `false` if there was nothing to send.
     * Must be followed by `sendPreparedChunk()` to actually send.
     */
    prepareChunk(len: number, first_is_local_root: boolean, chunk: Uint8Array): boolean;
    /**
     * Send the previously prepared chunk.
     *
     * Uses `&self` (not `&mut self`); exclusive access to the exporter is
     * enforced at runtime by the `sending` re-entrancy guard below rather
     * than by the borrow checker. WASM is single-threaded, so the only way
     * two `&mut` to the exporter could co-exist is async re-entrancy (JS
     * calling this again before the prior future resolves) — the guard
     * rejects that with an error instead of allowing aliasing (UB).
     */
    sendPreparedChunk(): Promise<any>;
    /**
     * Set default meta tags applied to every new span.
     * Takes a flat array of key-value pairs: [key1, val1, key2, val2, ...]
     */
    setDefaultMeta(pairs: any[]): void;
    setMetaStruct(span_id: bigint, key: string, value: Uint8Array): void;
    /**
     * Route trace export through libdatadog's OTLP HTTP exporter to `url`
     * instead of the Datadog agent. Must be called before the first send.
     * Takes precedence over `setUseV05` (OTLP bypasses the agent entirely).
     */
    setOtlpEndpoint(url: string): void;
    /**
     * Set extra HTTP headers for OTLP export as a flat `[key, value, ...]`
     * array (the host flattens its key/value map). Only takes effect with an
     * OTLP endpoint set, before the first send. A trailing unpaired element on
     * an odd-length array is ignored. Each call replaces any previously set headers.
     */
    setOtlpHeaders(kv: string[]): void;
    /**
     * Select the OTLP wire protocol: `http/json` (default) or `http/protobuf`.
     * Rejects unsupported values (e.g. `grpc`). Only takes effect with an OTLP
     * endpoint set, before the first send.
     */
    setOtlpProtocol(protocol: string): void;
    /**
     * Select v0.5 output for the trace exporter. Must be called before the
     * first `sendPreparedChunk` (the exporter is built lazily on first send and
     * the output format is fixed at build time; later calls have no effect).
     *
     * v0.5 silently drops `meta_struct` (and top-level `span_events`/`span_links`)
     * because the v0.5 wire schema has no slots for them — the caller is
     * responsible for only enabling this when the agent supports `/v0.5/traces`.
     */
    setUseV05(v: boolean): void;
    /**
     * Gracefully shut down the exporter and stop the background workers.
     * Should be awaited during tracer shutdown to avoid losing in-flight
     * data. Terminal and idempotent: it consumes the exporter (and the
     * builder, if the exporter was never built), so later sends error out
     * rather than silently starting a new exporter. Staged-but-unsent chunks
     * are dropped and `prepareChunk` errors afterwards, so flush before
     * shutting down.
     *
     * `timeoutMs` bounds the wait; on timeout returns an error and workers
     * may still be finishing. `None` waits indefinitely.
     */
    shutdown(timeout_ms?: number | null): Promise<void>;
    stringTableEvict(key: number): void;
    stringTableInsertMany(count: number): void;
    stringTableInsertOne(key: number, val: string): void;
    string_table_input_len(): number;
    string_table_input_ptr(): number;
}

/**
 * Export OpCode values as a JS object.
 * Values match the `#[repr(u64)]` OpCode enum in libdd-trace-utils.
 */
export function getOpCodes(): any;

/**
 * Export WASM memory so JS can create views into it
 */
export function getWasmMemory(): any;

export function init(): void;

declare function setResponseHeaderObserver2(observer: any): void;
export { setResponseHeaderObserver2 as setResponseHeaderObserver }

declare function setStorage2(new_storage: any): void;
export { setStorage2 as setStorage }
